/**
 * Adjusts the Xcode project generated by `tauri ios init` (gen/apple) so the
 * app can talk to its loopback proxy and to plain-HTTP IPTV sources:
 * App Transport Security must allow local networking and arbitrary loads.
 * Run after `tauri ios init`, before building.
 */
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..', 'src-tauri', 'gen', 'apple');
const plist = join(root, 'orivue-desktop_iOS', 'Info.plist');
if (!existsSync(plist)) {
  console.error(`Info.plist not found at ${plist}; run "pnpm tauri ios init" first.`);
  process.exit(1);
}
let content = readFileSync(plist, 'utf8');
if (!content.includes('NSAppTransportSecurity')) {
  content = content.replace(
    /<\/dict>\s*<\/plist>\s*$/,
    `\t<key>NSAppTransportSecurity</key>
\t<dict>
\t\t<key>NSAllowsArbitraryLoads</key>
\t\t<true/>
\t\t<key>NSAllowsLocalNetworking</key>
\t\t<true/>
\t</dict>
\t<key>UIRequiresFullScreen</key>
\t<true/>
\t<key>UISupportedInterfaceOrientations</key>
\t<array>
\t\t<string>UIInterfaceOrientationPortrait</string>
\t\t<string>UIInterfaceOrientationLandscapeLeft</string>
\t\t<string>UIInterfaceOrientationLandscapeRight</string>
\t</array>
</dict>
</plist>
`,
  );
  writeFileSync(plist, content);
  console.log('Info.plist patched with ATS exceptions and orientations.');
} else {
  console.log('Info.plist already configured.');
}
